solution.css:
body {
  background-color: #f2f4f8;
}

.spieler {
  background-color: white;
  width: 220px;
  border-radius: 16px;
  border: 1px solid #e0e4ee;
  padding: 16px;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.15);
}

.profil {
  width: 80px;
  height: 80px;
  border-radius: 50%;
}
